import unittest

import numpy as np

from sonic_mujoco.controllers.sonic import action_to_command
from sonic_mujoco.controllers.sonic.parameters import KD, KP

REFERENCE_ACTION = np.array(
    [0.36033609509468079, 0.52699214220046997, 0.27547883987426758,
     -0.81493759155273438, -0.46288877725601196, -0.0637216717004776,
     0.18710559606552124, -0.38644939661026001, -1.3728716373443604,
     -0.52416801452636719, 0.57196086645126343, 0.46841317415237427,
     0.0090556219220161438, 1.0547356605529785, 0.91527539491653442,
     -0.58151340484619141, -0.57457059621810913, 0.16631424427032471,
     0.093793570995330811, -0.28277236223220825, 0.37938651442527771,
     -0.64096832275390625, -1.3227121829986572, -0.39230704307556152,
     -0.20449690520763397, -0.79270368814468384, 0.046461734920740128,
     -0.041032701730728149, 0.19340436160564423]
)
REFERENCE_TARGET = np.array(
    [-0.18564401650487977, -0.28576721086110918, 0.10244900774747778,
     0.48519447539730726, 0.09958313290451376, 0.072941654519273785,
     -0.12720416264586532, -0.16231725740289413, -0.21159900109812008,
     0.86956463614110291, 0.038419024202642871, 0.041135732430412832,
     0.15083746501447221, -0.027946879613102112, -0.60211035506806476,
     0.40543539172606674, -0.055038587107874237, -0.12401754307956732,
     0.31888583469662585, -0.1720569691852985, -0.059057114680189156,
     -0.0030569719909103212, 0.2039715903384634, -0.45199362874868593,
     0.16639031843538712, 0.01988844368673548, -0.089687703391605561,
     0.0034614396886139941, 0.014408793265143209]
)


class SonicActionTest(unittest.TestCase):
    def test_cpp_golden_action_mapping(self) -> None:
        command = action_to_command(REFERENCE_ACTION)
        np.testing.assert_allclose(command.joint_position, REFERENCE_TARGET, atol=1e-12)
        np.testing.assert_array_equal(command.kp, KP)
        np.testing.assert_array_equal(command.kd, KD)
        np.testing.assert_array_equal(command.joint_velocity, 0.0)
        np.testing.assert_array_equal(command.feedforward_torque, 0.0)

    def test_action_rejects_wrong_shape(self) -> None:
        with self.assertRaises(ValueError):
            action_to_command(np.zeros(28))


if __name__ == "__main__":
    unittest.main()
